namespace ghidra.file.formats.ios.img4;






using org.bouncycastle.asn1;

using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.file.crypto;
using ghidra.file.crypto;
using ghidra.file.formats.ios.generic;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.task;

/* @FileSystemInfo(type = "img4", description = "iOS Img4", factory = typeof(GFileSystemBaseFactory)) */
public class Img4FileSystem : GFileSystemBase {

	private List<GFile> dataFileList = new();
	private byte[] decryptedBytes = new byte[0];

	public Img4FileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		try {
			byte[] magicBytes = provider.readBytes(0x0, 0x20);
			string magicString = new string(magicBytes);
			return magicString.indexOf("IM4P") != -1;
		}
		catch (Exception e) {
			//ignore...
		}
		return false;
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		monitor.setMessage("Opening IMG4...");
		try {
			ASN1InputStream asn1InputStream = new ASN1InputStream(provider.getInputStream(0));
			try {
				ASN1Primitive asn1Primitive = asn1InputStream.readObject();
				if (asn1Primitive is ASN1Sequence) {
					ASN1Sequence asn1Sequence = (ASN1Sequence) asn1Primitive;
					Enumeration<object> enumeration = asn1Sequence.getObjects();
					while (enumeration.hasMoreElements()) {
						if (monitor.isCancelled()) {
							break;
						}
						object nextElement = enumeration.nextElement();
						if (nextElement is DEROctetString) {
							DEROctetString octet = (DEROctetString) nextElement;

							byte[] encryptedBytes = octet.getOctets();

							FSRLRoot fsFSRL = getFSRL();

							CryptoKey cryptoKey = CryptoKey.NOT_ENCRYPTED_KEY;
							try {
								cryptoKey = CryptoKeyFactory.getCryptoKey(fsFSRL.getName(2),
									fileSystemName);
							}
							catch (IOException e) {
								monitor.setMessage(
									"WARNING: Crypto Key file not found! Trying unencrypted");
							}

							if (cryptoKey == CryptoKey.NOT_ENCRYPTED_KEY) {
								decryptedBytes = encryptedBytes;
							}
							else {
								iOS_AesCrypto aes = new iOS_AesCrypto(cryptoKey.key, cryptoKey.iv);
								decryptedBytes = aes.decrypt(encryptedBytes);
							}

							string filename = "im4p_data";
							GFileImpl dataFile = GFileImpl.fromPathString(this, root, filename,
								null, false, decryptedBytes.length);
							dataFileList.add(dataFile);

							break;
						}
					}
				}
			}
			finally {
				asn1InputStream.close();
			}
		}
		catch (Exception e) {
			throw new IOException("Error opening IMG4 file: ", e);
		}
	}

	/* @Override */
	public void close()
    {
		base.close();
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {
		if (dataFileList.contains(file)) {
			return new ByteArrayProvider(decryptedBytes, file.getFSRL());
		}
		throw new IOException("Unable to get DATA for " + file.getPath());
	}

	public Icon getIcon() {
		return null;
	}

	/* @Override */
	public List<GFile> getListing(GFile directory) {
		if (directory == null || directory.equals(root)) {
			return dataFileList;
		}
		return new();
	}

	public bool isDirectory(GFileImpl directory) {
		return directory.equals(root);
	}

	public bool isFile(GFileImpl file) {
		return !file.equals(root);
	}

}
